?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>سفارش‌های من | سوپرمارکت طهران</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:720px;margin:20px auto;padding:0 12px}.order{background:#fff;border:1px solid #e5ece6;border-radius:15px;padding:13px;margin:9px 0}.toprow{display:flex;justify-content:space-between;gap:8px}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}</style></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">👤</span><span><b>سفارش‌های من</b><small>ورود امن با موبایل</small></span></a><a class="btn pale" href="index.php">فروشگاه</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><?php if($phone===''):?><section class="panel"><h2>ورود با موبایل</h2><?php if(empty($_SESSION['otp_hash'])):?><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="request_otp"><label>شماره موبایل<input name="phone" inputmode="numeric" placeholder="09xxxxxxxxx" required></label><button class="btn wide">ارسال کد ورود</button></form><?php else:?><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="verify_otp"><label>کد ۶ رقمی<input name="code" inputmode="numeric" maxlength="6" required></label><button class="btn wide">ورود</button></form><?php endif;?><p class="muted">کد فقط ۵ دقیقه اعتبار دارد و هرگز داخل URL قرار نمی‌گیرد.</p></section><?php else:?><section class="panel"><div class="toprow"><div><h2><?=e($customer['name']??'مشتری طهران')?></h2><p><?=e($phone)?><?php if($customer):?><br><?=e($customer['address'])?><?php endif;?></p></div><a href="account.php?logout=1">خروج</a></div></section><section class="panel"><h2>سفارش‌های قبلی</h2><?php if(!$orders):?><p class="muted">هنوز سفارشی ندارید.</p><?php endif;?><?php foreach($orders as $o):?><div class="order"><div class="toprow"><b>سفارش #<?=(int)$o['id']?> · <?=e($labels[$o['status']]??$o['status'])?></b><strong><?=toman($o['total'])?></strong></div><div class="muted"><?=e($o['created_at'])?><?php if(!empty($o['delivery_zone_name'])):?> · <?=e($o['delivery_zone_name'])?><?php endif;?></div><div class="actions"><a class="btn pale" href="track.php?t=<?=e($o['public_token'])?>">پیگیری</a><?php if($o['status']!=='cancelled'):?><a class="btn pale" href="reorder.php?t=<?=e($o['public_token'])?>">🔁 سفارش مجدد</a><?php endif;?></div></div><?php endforeach;?></section><?php endif;?></main></body></html>
